mapper.select:
SELECT owner_id,task_id,session_id,question_id,answer_id,created_at
FROM ai_answer_rewrite
WHERE owner_id=#{owner} AND task_id=#{taskId}

SELECT COUNT(*) FROM ai_answer_rewrite r JOIN ai_task t ON t.owner_id=r.owner_id AND t.id=r.task_id
WHERE r.owner_id=#{owner} AND r.answer_id=#{answerId}
  AND t.status IN ('QUEUED','RUNNING','VALIDATING','CANCEL_REQUESTED')
AND r.task_id <> #{excludedTaskId}

SELECT t.id,t.purpose,t.status,t.revision,t.title,t.provider,t.model,t.currency,t.attempt_count,
  t.created_at,t.updated_at,t.error_code,r.question_id,r.answer_id,a.version_number AS answer_number
FROM ai_answer_rewrite r JOIN ai_task t ON t.owner_id=r.owner_id AND t.id=r.task_id
JOIN training_answer a ON a.owner_id=r.owner_id AND a.session_id=r.session_id
  AND a.question_id=r.question_id AND a.id=r.answer_id
WHERE r.owner_id=#{owner}
AND r.session_id=#{sessionId}
AND r.question_id=#{questionId}
AND r.answer_id=#{answerId}
AND t.id > #{cursor}
ORDER BY t.id LIMIT #{limit}
